// the name, and reads the day back out of a copy a day's (EXPORT_SIDES, AUTO_NAME in electron/main.cjs)
const FINANCE_FILE = "pnl-export";
const fileDay = (d = new Date()) => `${pad(d.getDate())}-${pad(d.getMonth() + 1)}-${d.getFullYear()}`;
const exportName = (file) => `${userFilePre()}${file}-${fileDay()}.json`;
