      times.sort((a, b) => a - b);
      list.forEach((a) => { try { a.pause(); } catch (e) {} });
      for (let i = 0; i < times.length && ok(); i++) {
        list.forEach((a, j) => { try { a.currentTime = Math.min(ends[j], times[i]); } catch (e) {} });
        move();
        await frame();
      }
      list.forEach((a) => { try { a.finish(); } catch (e) {} });
      await frame();
