/* goal progress bar: grows from 0 on mount, then eases between values */
// a goal's progress as a ring with its % in the middle (after his picture of a goal card)
const GoalRing = ({ pct, color, delay, children }) => {
  const R = 21, C = 2 * Math.PI * R, f = (C * Math.max(0, Math.min(100, pct))) / 100;
  return (
    <span className="goal-ring">
      <svg viewBox="0 0 52 52">
        <circle cx="26" cy="26" r={R} fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth="5.5" />
        <circle className="score-arc goal-arc" style={{ animationDelay: `${delay || 0}ms` }} cx="26" cy="26" r={R} fill="none" stroke={color}
                strokeWidth="5.5" strokeLinecap="round" strokeDasharray={`${f} ${C}`} />
      </svg>
      <span className="goal-ring-n">{children}</span>
    </span>
  );
};
const GoalBar = ({ pct, done, delay }) => {
  const [on, setOn] = useState(false);
  useEffect(() => {
    let r2;
    const r1 = requestAnimationFrame(() => { r2 = requestAnimationFrame(() => setOn(true)); });
    return () => { cancelAnimationFrame(r1); if (r2) cancelAnimationFrame(r2); };
  }, []);
  return (
    <div className="goal-track">
      {/* the fill is the track's whole width, slid in from the left (a moved surface, never a new width): its gradient
          starts where the track shows it, so it reads exactly as a fill that is only pct wide */}
      <div className={`goal-fill${done ? " done" : ""}`}
           style={{ transform: `translateX(${on ? Math.max(0, Math.min(100, pct)) - 100 : -100}%)`, "--gs": `${100 - Math.max(0, Math.min(100, pct))}%`,
                    transitionDelay: on ? `${delay || 0}ms` : "0ms" }} />
    </div>
  );
};

const SplitBar = ({ remainingVal, totalVal, frac, animKey }) => {
  const [on, setOn] = useState(false);
  useEffect(() => {
    setOn(false);
    let raf2;
    const raf1 = requestAnimationFrame(() => { raf2 = requestAnimationFrame(() => setOn(true)); });
    return () => { cancelAnimationFrame(raf1); if (raf2) cancelAnimationFrame(raf2); };
  }, [animKey]);
  const green = frac * 100;
  return (
    <div style={S.barTrack}>
      {/* left-to-right reveal: a window slides in while the bar inside slides the opposite way, so the bar
          stays put and is uncovered from the left. Both are GPU transforms — no relayout or repaint per frame. */}
      <div style={{ flex: "1 1 100%", width: "100%", height: "100%", overflow: "hidden", transform: on ? "translate3d(0,0,0)" : "translate3d(-100%,0,0)",
                    transition: on ? "transform .62s cubic-bezier(0.32,0.72,0.24,1)" : "none" }}>
      <div style={{ width: "100%", height: "100%", transform: on ? "translate3d(0,0,0)" : "translate3d(100%,0,0)",
                    transition: on ? "transform .62s cubic-bezier(0.32,0.72,0.24,1)" : "none" }}>
        {/* red fills the track; the green layer slides over it, so the green/red border moves by transform alone */}
        <div style={{ width: "100%", height: "100%", overflow: "hidden", background: totalVal > 0 ? "#ff5d6c" : "#2c3034",
                      transition: "background .3s ease" }}>
          <div style={{ width: "100%", height: "100%", background: remainColor(remainingVal), transform: `translate3d(${green - 100}%,0,0)`,
                        transition: "transform .5s cubic-bezier(0.32,0.72,0.24,1), background .3s ease" }} />
        </div>
      </div>
      </div>
    </div>
  );
};

/* ---------- the monthly spending rule (15 October 2026, his words: "a feature for a monthly spending rule … something
   like 70/30 rule, 70% spend and 30% save or the other way around", "find rules like this and others"; he chose: it
   tracks the month AND sets the daily limit, all four families, a section in Money flow and a line in the month's card,
   one rule for every month with any month allowed its own). A rule is a few parts, each a share of the month's income:
   a spend part is fed by categories (and, in two families, by symbols of Other), a save part by what is left of the
   income. The families and their presets, after the well-known methods:
   - Spend / save: 70/30, 30/70, 80/20 ("pay yourself first").
   - Needs / wants / save: 50/30/20 (Elizabeth Warren, All Your Worth), 60/20/20, and 70/20/10 read as living / saving /
     giving (the 10% fed by Other's charity, gift, wedding and family symbols).
   - 40/30/20/10, the Indonesian split: daily needs, obligations (bills, instalments), saving, social (zakat, donations).
   - The 60% Solution (Richard Jenkins): 60% committed costs, then 10% irregular (trips, repairs, the doctor), 10% fun,
     10% long-term saving and 10% retirement.
   An expense in Other with the Savings or the Investing symbol is money put aside: it counts toward saving, not spending. */
const RULE_SOCIAL = ["volunteer_activism", "redeem", "celebration", "family_restroom"];     // charity & zakat, gifts, weddings & parties, family
const RULE_IRREGULAR = ["luggage", "hotel", "build", "medical_services", "dentistry"];       // trips, hotel, repairs, doctor, dentist
const RULE_SAVED = ["savings", "trending_up"];
const RULE_FAMS = {
  ss: { name: "Spend / save", parts: [["spend", "Spend", "spend"], ["save", "Save", "save"]],
        presets: [["70/30", [70, 30]], ["30/70", [30, 70]], ["80/20", [80, 20]]],
        map: { food: "spend", transport: "spend", shopping: "spend", bills: "spend", other: "spend" } },
  nws: { name: "Needs / wants / save", parts: [["needs", "Needs", "spend"], ["wants", "Wants", "spend"], ["save", "Save", "save"]],
         presets: [["50/30/20", [50, 30, 20]], ["60/20/20", [60, 20, 20]]],
         map: { food: "needs", transport: "needs", bills: "needs", shopping: "wants", other: "wants" } },
  lsg: { name: "Living / save / give", parts: [["living", "Living", "spend"], ["save", "Save", "save"], ["give", "Giving", "spend"]],
         presets: [["70/20/10", [70, 20, 10]]], syms: { give: RULE_SOCIAL },
         map: { food: "living", transport: "living", shopping: "living", bills: "living", other: "living" } },
  idn: { name: "40/30/20/10", parts: [["daily", "Daily needs", "spend"], ["oblig", "Obligations", "spend"], ["save", "Save", "save"], ["social", "Social", "spend"]],
         presets: [["40/30/20/10", [40, 30, 20, 10]]], syms: { social: RULE_SOCIAL },
         map: { food: "daily", transport: "daily", shopping: "daily", bills: "oblig", other: "daily" } },
  sixty: { name: "60% Solution", parts: [["committed", "Committed", "spend"], ["irregular", "Irregular", "spend"], ["fun", "Fun", "spend"], ["long", "Long-term saving", "save"], ["retire", "Retirement", "save"]],
           presets: [["60% Solution", [60, 10, 10, 10, 10]]], syms: { irregular: RULE_IRREGULAR },
           map: { food: "committed", transport: "committed", bills: "committed", shopping: "fun", other: "fun" } },
};
// a rule from a family and its shares (a preset's, or his own), with the family's map of categories unless one is given.
// amount (22 October 2026, his words: "make me be able to input monthly pocket money / income in spending (this is
// optional, if unfilled then use whole income for the month"): the rupiah the shares are of each month, when set
const ruleFrom = (fam, pcts, map, limit = true, amount = 0) => {
  const F = RULE_FAMS[fam], preset = F.presets.find(([, p]) => p.join() === pcts.join());
  return { fam, name: preset ? preset[0] : pcts.join("/"), parts: F.parts.map(([k, label, kind], i) => ({ k, label, kind, pct: pcts[i] })),
           map: { ...F.map, ...(map || {}) }, limit, ...(amount > 0 ? { amount: Math.min(Math.round(amount), 1e13) } : {}) };
};
// a rule as saved: anything that doesn't add up is no rule (an empty or a broken one never sets a limit)
const cleanRule = (r) => {
  if (!r || typeof r !== "object" || !RULE_FAMS[r.fam] || !Array.isArray(r.parts)) return null;
  const F = RULE_FAMS[r.fam], pcts = F.parts.map(([k]) => { const p = r.parts.find((x) => x && x.k === k); return p && Number.isFinite(+p.pct) ? Math.max(0, Math.min(100, Math.round(+p.pct))) : NaN; });
  if (pcts.some((v) => !Number.isFinite(v)) || pcts.reduce((a, b) => a + b, 0) !== 100) return null;
  const spendKeys = F.parts.filter(([, , kind]) => kind === "spend").map(([k]) => k);
  const map = Object.fromEntries(Object.entries(F.map).map(([c, k]) => [c, r.map && spendKeys.includes(r.map[c]) ? r.map[c] : k]));
  return ruleFrom(r.fam, pcts, map, r.limit !== false, Number.isFinite(+r.amount) && +r.amount > 0 ? +r.amount : 0);
};
// the rules of the months that have their own: a month's rule, or false for "no rule this month". One made by the test
// data keeps its mark (test: true), so it stays out of a backup and goes with Clear test data
const cleanRuleByMonth = (v) => Object.fromEntries(Object.entries(v && typeof v === "object" ? v : {})
  .filter(([mk]) => /^\d{4}-\d{2}$/.test(mk)).map(([mk, r]) => { const c = r === false ? false : cleanRule(r); return [mk, c && r.test ? { ...c, test: true } : c]; })
  .filter(([, r]) => r !== null));
const ruleSpendPct = (r) => r.parts.reduce((a, p) => a + (p.kind === "spend" ? p.pct : 0), 0);
/* How a month stands against a rule. items: the month's expenses as { amount, cat, sym }; income: what the shares are
   of. Each part: its target (its share of the income), what it holds, and how it stands: a spend part "ok", "near" from
   90% of its target, "over" past it; a save part "ok" once its target is reached, else "short". What is left of the
   income goes to the save parts in turn, each up to its target, the last one taking the rest. */
const ruleStand = (r, income, items) => {
  const F = RULE_FAMS[r.fam], by = Object.fromEntries(r.parts.map((p) => [p.k, 0]));
  const spendKeys = r.parts.filter((p) => p.kind === "spend").map((p) => p.k);
  let spent = 0;
  for (const it of items) {
    if (RULE_SAVED.includes(it.sym)) continue;            // put aside: part of what is left, not spending
    const viaSym = F.syms && Object.entries(F.syms).find(([, list]) => list.includes(it.sym));
    const k = viaSym ? viaSym[0] : spendKeys.includes(r.map[it.cat]) ? r.map[it.cat] : spendKeys[0];
    by[k] += it.amount; spent += it.amount;
  }
  let left = Math.max(0, income - spent);
  const saves = r.parts.filter((p) => p.kind === "save");
  saves.forEach((p, i) => { const want = (income * p.pct) / 100, got = i === saves.length - 1 ? left : Math.min(left, want); by[p.k] = got; left -= got; });
  return r.parts.map((p) => {
    const target = (income * p.pct) / 100, got = by[p.k];
    const state = p.kind === "spend" ? (got > target ? "over" : got >= target * 0.9 && got > 0 ? "near" : "ok") : got >= target ? "ok" : "short";
    return { ...p, target, got, state };
  });
};
// the daily limit a rule gives a month: its spend share of the income, over the days of the month, in whole thousands
const ruleDaily = (r, income, days) => (r && r.limit && income > 0 ? Math.max(1000, Math.round((income * ruleSpendPct(r)) / 100 / days / 1000) * 1000) : null);
/* ---------- the monthly spending rule: end of the sums ---------- */

