/* Which category a note names, from the lists above. A word of a list counts where it stands as a word of its own in
   the note (a plural s allowed); one of 4 letters and up also at the start of a longer word ("shop" in "shopping",
   "kopi" in "kopiko"); only one of 5 and up inside or at the end of a word ("pants" in "sweatpants", "market" in
   "supermarket"). A word written with a space after it in its list ("es ", "train ") only counts as a word of its own,
   and one written with = before it ("=tiket", "=sewa", "=wifi") only when it is the whole note: beside another word
   it means too many things (tiket bioskop, sewa mobil, router wifi), and the AI reads those better.
   Before 11 October 2026 a word counted wherever its letters turned up: "sweatpants" was food for the "eat" in it (he
   reported that one), "steam" for its "tea", "business" transport for its "bus", and the AI, which has them right, is
   only asked about a note these lists can't place. When several fit, the best wins: a word of its own before a start
   before an inside, then the longer word; the order of the lists only settles a tie. Answers are kept: this is asked
   for every entry on every drawing of the panel. */
const listWords = (rules) => Object.entries(rules).flatMap(([cat, list], order) => list.map((raw) => ({ w: raw.replace("=", "").trim(), own: raw !== raw.trim(), alone: raw[0] === "=", cat, order })));
const CAT_WORDS = listWords(CAT_RULES);
const catWordChar = (c) => (c >= 97 && c <= 122) || (c >= 48 && c <= 57) || c > 127;       // a letter or a digit (the note is in lower case)
const CAT_SEEN = new Map();
const wordPick = (words, seen, desc) => {
  const d = (desc || "").toLowerCase().trim();
  if (!d) return null;
  if (seen.has(d)) return seen.get(d);
  let best = null, top = 0;
  for (const k of words) {
    const n = k.w.length;
    for (let at = d.indexOf(k.w); at >= 0; at = d.indexOf(k.w, at + 1)) {
      if (k.alone && (at > 0 || (d.length !== n && d !== `${k.w}s`))) break;
      const before = at > 0 && catWordChar(d.charCodeAt(at - 1));
      let after = catWordChar(d.charCodeAt(at + n));
      if (after && d[at + n] === "s" && !catWordChar(d.charCodeAt(at + n + 1))) after = false;      // a plural
      const kind = !before && !after ? 3 : k.own ? 0 : !before ? (n >= 4 ? 2 : 0) : n >= 5 ? 1 : 0;
      const score = kind ? kind * 1000 + n * 10 - k.order / 10 : 0;
      if (score > top) { top = score; best = k.cat; }
    }
  }
  if (seen.size > 4000) seen.clear();
  seen.set(d, best);
  return best;
};
/* Two things the lists can't say word by word (14 October 2026, measured on 9,000 labelled notes: 31 of the lists' 86
   wrong answers were a food word on a thing, 19 a thing with a service done to it):
   - a food word on a thing is the thing: "meja kopi", "sendok makan", "termos es", "grinder kopi", "steak knife",
     "snack kucing" are shopping (CAT_THINGS);
   - a thing, or a food word, with a service done to it is the service: "cuci sepatu", "jahit celana", "permak jeans",
     "reparasi tas", "coffee maker repair" are other (CAT_SERVICES).
   Read by the same matcher, so a word counts as it does in the lists (a space after it: only as a word of its own) */
const CAT_THINGS = listWords({ shopping: [
  "alat ", "piring ", "sendok", "garpu", "meja", "kursi", "lemari", "periuk", "termos", "thermos", "kertas", "mangkok ", "mangkuk ", "panci", "wajan",
  "saringan", "sabun", "masker", "juicer", "grinder", "blender", "maker", "cooker", "toaster", "kettle", "knife", "pisau",
  "lunch box", "tumbler", "kucing", "anjing", "hamster", "kelinci", "pet ", "cat ", "dog ",
] });
const CAT_SERVICES = listWords({ other: [
  "jahit", "permak", "vermak", "reparasi", "repair", "sablon", "sol sepatu", "cuci baju", "cuci sepatu", "laundry sepatu", "potong celana",
  "kursus", "course", "workshop",
] });
// what turns either rule off: a dish or a place that carries a thing's word ("nasi kucing", "soto saring", "sate kelinci",
// "bakmi gang kelinci" stay food), and what a service is done with, which is bought ("sabun cuci baju" stays shopping).
// A plate and a bowl are words of their own: "nasi sepiring" and "bakso semangkok" are food; a teapot and a strainer
// are not on the list at all ("es teh teko", "kopi saring" are drinks)
const CAT_DISHES = listWords({ food: ["nasi kucing", "soto saring", "gang kelinci", "sate kelinci", "kelinci bakar", "tongseng kelinci", "martabak kertas"] });
const CAT_SUPPLIES = listWords({ shopping: ["sabun", "detergen", "deterjen", "pewangi", "softener"] });
const THING_SEEN = new Map(), SERVICE_SEEN = new Map(), DISH_SEEN = new Map(), SUPPLY_SEEN = new Map();
const inferCat = (desc) => {
  const c = wordPick(CAT_WORDS, CAT_SEEN, desc);
  if ((c === "food" || c === "shopping") && wordPick(CAT_SERVICES, SERVICE_SEEN, desc) && !wordPick(CAT_SUPPLIES, SUPPLY_SEEN, desc)) return "other";
  return c === "food" && wordPick(CAT_THINGS, THING_SEEN, desc) && !wordPick(CAT_DISHES, DISH_SEEN, desc) ? "shopping" : c;
};

